insert into public.pathways (id, content, checked_on, reviewed_by) values
  ('student', '{"id":"student","name":"Study a Masters","short":"Student → Masters","tint":"malibu","icon":"graduation","summary":"Study a postgraduate qualification in New Zealand, gain local work experience on a post-study work visa, then aim for residence through a skilled job.","whoFor":["You have a bachelor''s degree, or will soon","You can show money for tuition and living costs","You want an NZ qualification and NZ work experience before deciding on residence"],"steps":[{"title":"Choose a programme and university","detail":"Shortlist programmes that build on your degree and lead to jobs in demand. Check entry requirements, intakes and fees on each university''s own website."},{"title":"Meet the English requirement","detail":"Universities set their own English entry levels. Many Masters programmes ask for an academic IELTS around 6.5 overall, or an equivalent PTE or TOEFL score."},{"title":"Get an offer of place","detail":"Apply directly or through a licensed agent. You''ll receive an offer of place once you meet the entry requirements."},{"title":"Show your funds","detail":"You must show you can pay tuition and living costs. Immigration NZ asks for evidence of NZD 20,000 for each year of study for living costs, plus funds for an onward ticket."},{"title":"Apply for a student visa","detail":"Apply online with Immigration New Zealand. Longer courses usually need a medical certificate, chest X-ray and police certificate."},{"title":"Study and work part-time","detail":"Student visas granted since 3 November 2025 usually allow up to 25 hours of work a week in term and full-time work in scheduled breaks. Check the conditions printed on your own visa."},{"title":"Post-study work visa","detail":"After finishing an eligible qualification you may be able to get an open work visa for up to 3 years, depending on the qualification and where you studied."},{"title":"Move towards residence","detail":"A skilled job and NZ work experience can lead to residence through the Green List or the Skilled Migrant Category."}],"requirements":["Offer of place from an approved New Zealand education provider","Tuition paid, or evidence you can pay it","Funds for living costs (NZD 20,000 per year of study) and onward travel","Medical, chest X-ray and police certificate if your course is long enough to need them","International student insurance for your whole stay"],"timeline":"Start 9 to 12 months before your intake","residence":"No direct residence. Graduate, work in a skilled role, then apply through the Green List or the Skilled Migrant Category.","watchOuts":["Not every course leads to a post-study work visa. Check eligibility before you pay a deposit.","Partners of Masters and PhD students may qualify for a partner work visa. Check the current rules before you apply.","An agent who promises a guaranteed visa is a red flag. No one can guarantee an Immigration NZ decision."],"sources":[{"label":"Immigration New Zealand","href":"https://www.immigration.govt.nz"},{"label":"Study with New Zealand","href":"https://www.studywithnewzealand.govt.nz"},{"label":"NZQA: overseas qualification recognition","href":"https://www.nzqa.govt.nz"},{"label":"Immigration Advisers Authority (find a licensed adviser)","href":"https://www.iaa.govt.nz"}],"checked":"Nov 2026","documents":["passport","photo","transcripts","degree","english","offer","funds","sponsor","police","medical","insurance","cv"],"levels":[{"id":"student.start","title":"Find your path","summary":"Understand the study route and check it fits your goals.","icon":"compass","tasks":[{"id":"common.finder","title":"Complete the Pathway Finder","detail":"Answer a few questions so KiwiPath can suggest the paths that suit you.","xp":40,"link":{"to":"/welcome","label":"Open Pathway Finder"}},{"id":"student.start.guide","title":"Read the Masters path guide","detail":"See every stage from offer to residence in one place.","xp":10,"link":{"to":"/paths/student","label":"Open guide"}},{"id":"student.start.field","title":"Pick two job areas you''d like to work in","detail":"Choose a programme for the career it leads to, not only the subject. Careers New Zealand lists job outlooks and pay ranges.","xp":15,"link":{"href":"https://www.careers.govt.nz","label":"Careers NZ"}}]},{"id":"student.english","title":"English test","summary":"Prepare, book and pass the test your universities accept.","icon":"mic","tasks":[{"id":"student.english.choose","title":"Choose IELTS Academic, PTE Academic or TOEFL","detail":"Check which tests and scores your shortlisted programmes accept. IELTS General is not usually accepted for university entry.","xp":15},{"id":"common.speaking","title":"Do three speaking practice sessions","detail":"Record yourself answering test-style questions and track your pace, filler words and pauses.","xp":30,"link":{"to":"/tools/english","label":"Open English Coach"}},{"id":"student.english.book","title":"Book your test date","detail":"Leave time for a retake before application deadlines.","xp":20},{"id":"student.english.score","title":"Get your score report","detail":"Keep the test report form number; universities use it to verify your score.","xp":30}]},{"id":"student.courses","title":"Courses & offers","summary":"Shortlist programmes, apply and accept an offer of place.","icon":"school","tasks":[{"id":"student.courses.shortlist","title":"Shortlist three programmes","detail":"Compare fees, intakes, entry scores and deadlines side by side.","xp":20,"link":{"to":"/tools/courses","label":"Open Course Shortlist"}},{"id":"student.courses.sop","title":"Write your statement of purpose","detail":"Explain why this programme, why New Zealand and what you will do afterwards. Keep it specific and honest.","xp":20},{"id":"student.courses.refs","title":"Ask two referees for letters","detail":"Academic or work referees who know you well. Give them at least three weeks.","xp":15},{"id":"student.courses.apply","title":"Submit your applications","detail":"Upload certified transcripts, your degree, English results and CV.","xp":25},{"id":"student.courses.offer","title":"Accept an offer of place","detail":"Read the refund policy before you pay a tuition deposit.","xp":30}]},{"id":"student.money","title":"Funds & budget","summary":"Plan tuition, living costs and the proof Immigration NZ asks for.","icon":"wallet","tasks":[{"id":"common.budget","title":"Build your moving budget","detail":"Add up visa, travel and set-up costs in NZD and rupees, and set a monthly savings goal.","xp":30,"link":{"to":"/tools/money","label":"Open Money Planner"}},{"id":"student.money.proof","title":"Gather proof of funds","detail":"Bank statements showing funds held over time, education loan approval letters, or sponsor documents. Sudden large deposits raise questions.","xp":25},{"id":"student.money.sponsor","title":"Prepare sponsor documents if family is supporting you","detail":"Sponsors usually show their relationship to you, their income and their savings.","xp":15},{"id":"student.money.goal","title":"Set a monthly savings goal","detail":"Turn the gap into a monthly amount you can track.","xp":10,"link":{"to":"/tools/money","label":"Set goal"}}]},{"id":"student.docs","title":"Documents","summary":"Collect certificates early: some take weeks.","icon":"files","tasks":[{"id":"common.passport","title":"Check your passport''s expiry date","detail":"Your passport should stay valid for your whole planned stay. Renew early: it is the first document every application asks for.","xp":10,"link":{"to":"/tools/documents","label":"Open Documents"}},{"id":"common.police","title":"Request a police clearance certificate","detail":"Most visas lasting longer than a short visit need a police certificate from each country you have lived in for a set period. In Sri Lanka these come from Sri Lanka Police.","xp":20,"link":{"href":"https://www.police.lk","label":"Sri Lanka Police"}},{"id":"common.medical","title":"Book your medical and chest X-ray if asked","detail":"Longer stays usually need a medical certificate and/or chest X-ray from an Immigration NZ panel physician. Check which ones your visa needs before you book.","xp":20},{"id":"common.translations","title":"Get certified translations of Sinhala or Tamil documents","detail":"Documents not in English (birth and marriage certificates, for example) need certified English translations.","xp":15,"link":{"to":"/tools/documents","label":"Track documents"}}]},{"id":"student.visa","title":"Visa application","summary":"Apply with Immigration New Zealand and stay safe from scams.","icon":"stamp","tasks":[{"id":"common.scam-check","title":"Check any agent or offer with Scam Shield","detail":"Paste a WhatsApp message, email or offer letter. Scam Shield flags upfront fees, visa guarantees and other warning signs.","xp":30,"link":{"to":"/tools/scam-shield","label":"Open Scam Shield"}},{"id":"common.adviser","title":"Confirm any adviser is licensed","detail":"In New Zealand law, anyone giving you immigration advice (in NZ or overseas) must be a licensed immigration adviser or a lawyer, unless exempt. Ask for their licence number and check it on the public register.","xp":20,"link":{"href":"https://www.iaa.govt.nz","label":"Search the register"}},{"id":"student.visa.account","title":"Create your Immigration NZ online account","detail":"Apply online. Keep your login details and application number safe.","xp":10,"link":{"href":"https://www.immigration.govt.nz","label":"Immigration NZ"}},{"id":"student.visa.submit","title":"Submit your student visa application","detail":"Upload every document in English and pay the fee online.","xp":40},{"id":"student.visa.respond","title":"Reply quickly to any requests","detail":"Immigration NZ may ask for more information. Missing a deadline can delay or end your application.","xp":15}]},{"id":"student.fly","title":"Get ready to fly","summary":"Flights, a place to stay and knowing what to expect.","icon":"plane","tasks":[{"id":"student.fly.insurance","title":"Buy international student insurance","detail":"Insurance is a condition of study for international students. Many universities offer a default policy.","xp":15},{"id":"student.fly.stay","title":"Arrange your first weeks of accommodation","detail":"University halls, homestays or a short-term rental while you look for a flat.","xp":20},{"id":"student.fly.flights","title":"Book flights for orientation week","detail":"Arrive before orientation so you can settle in and set up accounts.","xp":15},{"id":"common.biosecurity","title":"Pack for New Zealand''s border rules","detail":"New Zealand has strict biosecurity rules. Declare all food, plants and animal products on your arrival card, or leave them at home. Undeclared items can mean an instant fine.","xp":10},{"id":"common.quiz","title":"Score 80% on the Kiwi Life quiz","detail":"Slang, road rules, renting and work basics: the things nobody tells you before you land.","xp":30,"link":{"to":"/tools/quiz","label":"Play Kiwi Life"}}]},{"id":"student.arrive","title":"First 30 days","summary":"Set up the basics so work, study and everyday life run smoothly.","icon":"home","tasks":[{"id":"common.ird","title":"Apply for an IRD number","detail":"Your tax number from Inland Revenue. Apply as soon as you arrive; employers need it to pay you at the right tax rate.","xp":20,"link":{"href":"https://www.ird.govt.nz","label":"Inland Revenue"}},{"id":"common.bank","title":"Open a New Zealand bank account","detail":"Some banks let you start the process before you arrive. Bring your passport and proof of address.","xp":15},{"id":"common.sim","title":"Get a local SIM or eSIM","detail":"You''ll need an NZ mobile number for banks, employers and two-factor codes. Prepaid plans are easy to start with.","xp":10},{"id":"common.gp","title":"Enrol with a GP (family doctor)","detail":"Enrolling with a local medical centre makes appointments easier and can make them cheaper if you are eligible for public health funding.","xp":15},{"id":"common.rights","title":"Learn your work rights","detail":"Every worker in NZ has the same minimum rights: a written employment agreement, at least minimum wage, holidays and sick leave. Your visa may add limits on hours or employer.","xp":15,"link":{"href":"https://www.employment.govt.nz","label":"Employment NZ"}},{"id":"student.arrive.rent","title":"Know your renting rights before you sign","detail":"A bond can be at most four weeks'' rent, and your landlord must lodge it with Tenancy Services. Never pay a bond in cash without a receipt.","xp":15,"link":{"href":"https://www.tenancy.govt.nz","label":"Tenancy Services"}}]},{"id":"student.after","title":"After graduation","summary":"Turn your qualification into work and, later, residence.","icon":"trend","tasks":[{"id":"common.cv","title":"Make an NZ-style CV","detail":"Two to three pages, achievements over duties, and no photo, date of birth, NIC number or religion.","xp":30,"link":{"to":"/tools/cv","label":"Open CV Studio"}},{"id":"student.after.psw","title":"Check your post-study work visa eligibility","detail":"Apply before your student visa expires. Eligibility depends on your qualification and how long you studied in NZ.","xp":30},{"id":"student.after.residence","title":"Map your route to residence","detail":"Compare the Green List and Skilled Migrant Category against the jobs you are targeting.","xp":20,"link":{"to":"/paths/worker","label":"See skilled worker path"}}]}]}'::jsonb, '2026-11-04', 'KiwiPath content team (needs licensed adviser review)'),
  ('worker', '{"id":"worker","name":"Skilled worker","short":"Job offer → Work visa","tint":"gold","icon":"briefcase","summary":"Get a job offer from an accredited New Zealand employer, move on an Accredited Employer Work Visa (AEWV), then build towards residence.","whoFor":["You have skills and experience that NZ employers need","You can get a job offer from an accredited employer","You meet any registration or English requirement for your role"],"steps":[{"title":"Check demand for your occupation","detail":"Look up your occupation on the Green List and other occupation lists on immigration.govt.nz, and check whether NZ law requires registration for it."},{"title":"Get your skills recognised","detail":"Regulated jobs need NZ registration before you can work. NZQA can assess overseas qualifications when your visa or residence application needs it."},{"title":"Prepare an NZ-style CV","detail":"Kiwi employers expect a short, achievement-focused CV without a photo, age, religion or marital status."},{"title":"Find an accredited employer","detail":"Only employers accredited by Immigration NZ can hire you on an AEWV. Check accreditation on the official list before you accept anything."},{"title":"Employer completes a Job Check","detail":"The employer confirms the pay and conditions meet the rules and, for most roles, that they advertised for New Zealanders first. You then receive a job token."},{"title":"Apply for your AEWV","detail":"Apply online with your job token, passport, qualification and experience evidence, medical and police certificates. Some roles also need proof of English."},{"title":"Move and start work","detail":"Work for your employer within your visa conditions. Keep payslips, your employment agreement and records of your duties."},{"title":"Move towards residence","detail":"Depending on your role and pay: Green List Straight to Residence or Work to Residence, or one of the Skilled Migrant Category pathways."}],"requirements":["Job offer from an Immigration NZ accredited employer","An approved Job Check (job token) for your role","The qualifications or experience the role requires","Proof of English for some roles (requirements were widened in 2026, so check yours)","Health and character requirements (medical and police certificates)"],"timeline":"Often 6 to 18 months, mostly spent finding the right job","residence":"Green List (Straight to Residence, or Work to Residence after 2 years), or the Skilled Migrant Category: the points-based, skilled work experience, or trades and technician pathways.","watchOuts":["Never pay for a job offer. NZ law does not allow employers to charge a premium for a job.","Check the employer is accredited before you resign from your job in Sri Lanka or pay anyone.","Your AEWV is tied to your employer and role. Changing jobs needs a new visa or a change of conditions."],"sources":[{"label":"Immigration New Zealand","href":"https://www.immigration.govt.nz"},{"label":"NZQA: overseas qualification recognition","href":"https://www.nzqa.govt.nz"},{"label":"Employment New Zealand (work rights)","href":"https://www.employment.govt.nz"},{"label":"Immigration Advisers Authority (find a licensed adviser)","href":"https://www.iaa.govt.nz"}],"checked":"Nov 2026","documents":["passport","photo","degree","transcripts","experience","english","contract","police","medical","cv"],"levels":[{"id":"worker.start","title":"Find your path","summary":"Check your occupation and the routes open to you.","icon":"compass","tasks":[{"id":"common.finder","title":"Complete the Pathway Finder","detail":"Answer a few questions so KiwiPath can suggest the paths that suit you.","xp":40,"link":{"to":"/welcome","label":"Open Pathway Finder"}},{"id":"worker.start.occupation","title":"Check your occupation","detail":"See whether your job is regulated in NZ and who registers it.","xp":20,"link":{"to":"/tools/occupations","label":"Open Occupation Check"}},{"id":"worker.start.guide","title":"Read the skilled worker guide","detail":"Every stage from job search to residence.","xp":10,"link":{"to":"/paths/worker","label":"Open guide"}}]},{"id":"worker.recognised","title":"Get recognised","summary":"Registration, qualification assessment and reference letters.","icon":"badge","tasks":[{"id":"worker.recognised.registration","title":"Start registration if your job needs it","detail":"Registration can take months. Start before job hunting if your occupation is regulated.","xp":30},{"id":"worker.recognised.nzqa","title":"Check whether you need an NZQA assessment","detail":"Some residence pathways and employers need your qualification assessed against the NZ framework.","xp":20,"link":{"href":"https://www.nzqa.govt.nz","label":"NZQA"}},{"id":"worker.recognised.refs","title":"Collect detailed reference letters","detail":"Letters on company letterhead with your title, dates, hours, salary and main duties. Immigration NZ uses them to check your experience.","xp":25}]},{"id":"worker.english","title":"English","summary":"Find out whether your role needs a test, and practise either way.","icon":"mic","tasks":[{"id":"worker.english.check","title":"Check if your role needs an English test","detail":"Requirements depend on the role''s skill level. Check before you apply.","xp":10},{"id":"common.speaking","title":"Do three speaking practice sessions","detail":"Record yourself answering test-style questions and track your pace, filler words and pauses.","xp":30,"link":{"to":"/tools/english","label":"Open English Coach"}},{"id":"worker.english.book","title":"Book a test if you need one","detail":"IELTS, PTE and other tests are accepted. Check which scores apply.","xp":20}]},{"id":"worker.jobs","title":"CV & job search","summary":"Market yourself the way Kiwi employers expect.","icon":"search","tasks":[{"id":"common.cv","title":"Make an NZ-style CV","detail":"Two to three pages, achievements over duties, and no photo, date of birth, NIC number or religion.","xp":30,"link":{"to":"/tools/cv","label":"Open CV Studio"}},{"id":"worker.jobs.linkedin","title":"Update your LinkedIn profile","detail":"Match your CV, add the NZ city you are targeting, and say whether you need visa sponsorship.","xp":15},{"id":"worker.jobs.shortlist","title":"Shortlist ten accredited employers","detail":"Focus on employers that already hire overseas workers in your field.","xp":20},{"id":"worker.jobs.apply","title":"Send ten tailored applications","detail":"Tailor each CV summary and cover letter to the job ad''s wording.","xp":30}]},{"id":"worker.offer","title":"Job offer","summary":"Make sure the offer is real before you rely on it.","icon":"handshake","tasks":[{"id":"common.scam-check","title":"Check any agent or offer with Scam Shield","detail":"Paste a WhatsApp message, email or offer letter. Scam Shield flags upfront fees, visa guarantees and other warning signs.","xp":30,"link":{"to":"/tools/scam-shield","label":"Open Scam Shield"}},{"id":"worker.offer.accredited","title":"Confirm the employer is accredited","detail":"Check the official accredited employer list on immigration.govt.nz.","xp":20,"link":{"href":"https://www.immigration.govt.nz","label":"Immigration NZ"}},{"id":"worker.offer.agreement","title":"Read your employment agreement","detail":"It must be in writing and list your pay, hours, duties and location. Ask questions before you sign.","xp":20},{"id":"worker.offer.jobcheck","title":"Get your job token","detail":"Your employer''s approved Job Check gives you the token you need to apply.","xp":25}]},{"id":"worker.visa","title":"Visa application","summary":"Certificates, application and safe handling of your documents.","icon":"stamp","tasks":[{"id":"common.passport","title":"Check your passport''s expiry date","detail":"Your passport should stay valid for your whole planned stay. Renew early: it is the first document every application asks for.","xp":10,"link":{"to":"/tools/documents","label":"Open Documents"}},{"id":"common.police","title":"Request a police clearance certificate","detail":"Most visas lasting longer than a short visit need a police certificate from each country you have lived in for a set period. In Sri Lanka these come from Sri Lanka Police.","xp":20,"link":{"href":"https://www.police.lk","label":"Sri Lanka Police"}},{"id":"common.medical","title":"Book your medical and chest X-ray if asked","detail":"Longer stays usually need a medical certificate and/or chest X-ray from an Immigration NZ panel physician. Check which ones your visa needs before you book.","xp":20},{"id":"common.translations","title":"Get certified translations of Sinhala or Tamil documents","detail":"Documents not in English (birth and marriage certificates, for example) need certified English translations.","xp":15,"link":{"to":"/tools/documents","label":"Track documents"}},{"id":"common.adviser","title":"Confirm any adviser is licensed","detail":"In New Zealand law, anyone giving you immigration advice (in NZ or overseas) must be a licensed immigration adviser or a lawyer, unless exempt. Ask for their licence number and check it on the public register.","xp":20,"link":{"href":"https://www.iaa.govt.nz","label":"Search the register"}},{"id":"worker.visa.submit","title":"Submit your AEWV application","detail":"Apply online with your job token and documents.","xp":40}]},{"id":"worker.move","title":"Money & move","summary":"Plan for the gap between landing and your first pay.","icon":"plane","tasks":[{"id":"common.budget","title":"Build your moving budget","detail":"Add up visa, travel and set-up costs in NZD and rupees, and set a monthly savings goal.","xp":30,"link":{"to":"/tools/money","label":"Open Money Planner"}},{"id":"worker.move.buffer","title":"Save for at least four weeks before first pay","detail":"Rent in advance, bond, transport and food add up quickly in the first month.","xp":20},{"id":"worker.move.stay","title":"Book temporary accommodation","detail":"Two to four weeks gives you time to view flats in person.","xp":15},{"id":"common.biosecurity","title":"Pack for New Zealand''s border rules","detail":"New Zealand has strict biosecurity rules. Declare all food, plants and animal products on your arrival card, or leave them at home. Undeclared items can mean an instant fine.","xp":10},{"id":"common.quiz","title":"Score 80% on the Kiwi Life quiz","detail":"Slang, road rules, renting and work basics: the things nobody tells you before you land.","xp":30,"link":{"to":"/tools/quiz","label":"Play Kiwi Life"}}]},{"id":"worker.arrive","title":"First 30 days","summary":"Set up the basics so work, study and everyday life run smoothly.","icon":"home","tasks":[{"id":"common.ird","title":"Apply for an IRD number","detail":"Your tax number from Inland Revenue. Apply as soon as you arrive; employers need it to pay you at the right tax rate.","xp":20,"link":{"href":"https://www.ird.govt.nz","label":"Inland Revenue"}},{"id":"common.bank","title":"Open a New Zealand bank account","detail":"Some banks let you start the process before you arrive. Bring your passport and proof of address.","xp":15},{"id":"common.sim","title":"Get a local SIM or eSIM","detail":"You''ll need an NZ mobile number for banks, employers and two-factor codes. Prepaid plans are easy to start with.","xp":10},{"id":"common.gp","title":"Enrol with a GP (family doctor)","detail":"Enrolling with a local medical centre makes appointments easier and can make them cheaper if you are eligible for public health funding.","xp":15},{"id":"common.rights","title":"Learn your work rights","detail":"Every worker in NZ has the same minimum rights: a written employment agreement, at least minimum wage, holidays and sick leave. Your visa may add limits on hours or employer.","xp":15,"link":{"href":"https://www.employment.govt.nz","label":"Employment NZ"}},{"id":"worker.arrive.rent","title":"Know your renting rights before you sign","detail":"A bond can be at most four weeks'' rent, and your landlord must lodge it with Tenancy Services. Never pay a bond in cash without a receipt.","xp":15,"link":{"href":"https://www.tenancy.govt.nz","label":"Tenancy Services"}}]},{"id":"worker.residence","title":"Residence","summary":"Build the record you''ll need for a residence application.","icon":"trend","tasks":[{"id":"worker.residence.track","title":"Keep payslips and records","detail":"Your NZ work experience and pay history are evidence for residence.","xp":15},{"id":"worker.residence.route","title":"Check which residence pathway fits","detail":"Green List, Skilled Migrant points, skilled work experience, or trades and technician.","xp":20},{"id":"worker.residence.advice","title":"Get licensed advice before you apply","detail":"Residence applications are expensive and detailed. A licensed adviser can check your evidence first.","xp":15,"link":{"href":"https://www.iaa.govt.nz","label":"Find an adviser"}}]}]}'::jsonb, '2026-11-04', 'KiwiPath content team (needs licensed adviser review)'),
  ('registered', '{"id":"registered","name":"Registered professional","short":"Registration → Job → Visa","tint":"pink","icon":"badge","summary":"For regulated jobs such as nursing, medicine, teaching and electrical work. Get NZ registration first, then a job offer and visa. Many registered roles are on the Green List.","whoFor":["You work in a job that NZ law regulates","You can meet the regulator''s qualification, experience and English standards","You''re ready for a registration process that can take several months"],"steps":[{"title":"Find your regulator","detail":"Each regulated job has its own body, such as the Nursing Council of New Zealand or the Teaching Council. Use Occupation Check to find yours."},{"title":"Apply for registration","detail":"The regulator assesses your qualification, experience and English. Their English standard is often higher than the visa standard."},{"title":"Complete any bridging requirements","detail":"Some regulators ask for a competence programme, exam or supervised practice in New Zealand."},{"title":"Get a job offer","detail":"Most roles need an offer from an accredited employer. Registration makes you far more attractive to employers."},{"title":"Apply for your visa","detail":"Usually an Accredited Employer Work Visa. Some Green List Tier 1 roles can apply straight to residence."},{"title":"Settle and grow your career","detail":"Keep your practising certificate current and record your NZ experience for residence."}],"requirements":["Registration, or provisional registration, with the NZ regulator for your job","The regulator''s English standard","A job offer, usually from an accredited employer","Health and character requirements"],"timeline":"Often 9 to 24 months, depending on registration","residence":"Many registered roles are on the Green List. Others can use the Skilled Migrant Category, where NZ registration can earn points.","watchOuts":["Only the regulator can register you. Be wary of anyone selling a guaranteed registration.","Keep originals and certified copies of transcripts, registrations and certificates of good standing."],"sources":[{"label":"Immigration New Zealand","href":"https://www.immigration.govt.nz"},{"label":"Careers New Zealand","href":"https://www.careers.govt.nz"},{"label":"Immigration Advisers Authority (find a licensed adviser)","href":"https://www.iaa.govt.nz"}],"checked":"Nov 2026","documents":["passport","degree","transcripts","registration","goodstanding","experience","english","police","medical","cv"],"levels":[{"id":"registered.start","title":"Find your path","summary":"Identify your regulator and what it asks for.","icon":"compass","tasks":[{"id":"common.finder","title":"Complete the Pathway Finder","detail":"Answer a few questions so KiwiPath can suggest the paths that suit you.","xp":40,"link":{"to":"/welcome","label":"Open Pathway Finder"}},{"id":"registered.start.regulator","title":"Find your regulator","detail":"Look up your occupation to see who registers it.","xp":20,"link":{"to":"/tools/occupations","label":"Open Occupation Check"}}]},{"id":"registered.registration","title":"Registration","summary":"The longest step. Start it first.","icon":"badge","tasks":[{"id":"registered.registration.standard","title":"Read your regulator''s requirements","detail":"Note the English score, documents and fees they need.","xp":15},{"id":"registered.registration.goodstanding","title":"Request certificates of good standing","detail":"From each body that has registered you, such as the Sri Lanka Medical Council or Sri Lanka Nursing Council.","xp":20},{"id":"registered.registration.english","title":"Reach the regulator''s English score","detail":"Their standard can be higher than the visa standard.","xp":30,"link":{"to":"/tools/english","label":"Practise speaking"}},{"id":"registered.registration.apply","title":"Submit your registration application","detail":"Keep copies of everything you send.","xp":40}]},{"id":"registered.jobs","title":"Job search","summary":"Employers in regulated fields often recruit from overseas.","icon":"search","tasks":[{"id":"common.cv","title":"Make an NZ-style CV","detail":"Two to three pages, achievements over duties, and no photo, date of birth, NIC number or religion.","xp":30,"link":{"to":"/tools/cv","label":"Open CV Studio"}},{"id":"common.scam-check","title":"Check any agent or offer with Scam Shield","detail":"Paste a WhatsApp message, email or offer letter. Scam Shield flags upfront fees, visa guarantees and other warning signs.","xp":30,"link":{"to":"/tools/scam-shield","label":"Open Scam Shield"}},{"id":"registered.jobs.offer","title":"Accept a written job offer","detail":"Check the employer''s accreditation and read the agreement.","xp":30}]},{"id":"registered.visa","title":"Visa application","summary":"Certificates and your application.","icon":"stamp","tasks":[{"id":"common.passport","title":"Check your passport''s expiry date","detail":"Your passport should stay valid for your whole planned stay. Renew early: it is the first document every application asks for.","xp":10,"link":{"to":"/tools/documents","label":"Open Documents"}},{"id":"common.police","title":"Request a police clearance certificate","detail":"Most visas lasting longer than a short visit need a police certificate from each country you have lived in for a set period. In Sri Lanka these come from Sri Lanka Police.","xp":20,"link":{"href":"https://www.police.lk","label":"Sri Lanka Police"}},{"id":"common.medical","title":"Book your medical and chest X-ray if asked","detail":"Longer stays usually need a medical certificate and/or chest X-ray from an Immigration NZ panel physician. Check which ones your visa needs before you book.","xp":20},{"id":"common.adviser","title":"Confirm any adviser is licensed","detail":"In New Zealand law, anyone giving you immigration advice (in NZ or overseas) must be a licensed immigration adviser or a lawyer, unless exempt. Ask for their licence number and check it on the public register.","xp":20,"link":{"href":"https://www.iaa.govt.nz","label":"Search the register"}},{"id":"registered.visa.submit","title":"Submit your visa application","detail":"AEWV, or Straight to Residence if your role qualifies.","xp":40}]},{"id":"registered.move","title":"Get ready to fly","summary":"Budget, travel and settling in.","icon":"plane","tasks":[{"id":"common.budget","title":"Build your moving budget","detail":"Add up visa, travel and set-up costs in NZD and rupees, and set a monthly savings goal.","xp":30,"link":{"to":"/tools/money","label":"Open Money Planner"}},{"id":"common.biosecurity","title":"Pack for New Zealand''s border rules","detail":"New Zealand has strict biosecurity rules. Declare all food, plants and animal products on your arrival card, or leave them at home. Undeclared items can mean an instant fine.","xp":10},{"id":"common.quiz","title":"Score 80% on the Kiwi Life quiz","detail":"Slang, road rules, renting and work basics: the things nobody tells you before you land.","xp":30,"link":{"to":"/tools/quiz","label":"Play Kiwi Life"}}]},{"id":"registered.arrive","title":"First 30 days","summary":"Set up the basics so work, study and everyday life run smoothly.","icon":"home","tasks":[{"id":"common.ird","title":"Apply for an IRD number","detail":"Your tax number from Inland Revenue. Apply as soon as you arrive; employers need it to pay you at the right tax rate.","xp":20,"link":{"href":"https://www.ird.govt.nz","label":"Inland Revenue"}},{"id":"common.bank","title":"Open a New Zealand bank account","detail":"Some banks let you start the process before you arrive. Bring your passport and proof of address.","xp":15},{"id":"common.sim","title":"Get a local SIM or eSIM","detail":"You''ll need an NZ mobile number for banks, employers and two-factor codes. Prepaid plans are easy to start with.","xp":10},{"id":"common.gp","title":"Enrol with a GP (family doctor)","detail":"Enrolling with a local medical centre makes appointments easier and can make them cheaper if you are eligible for public health funding.","xp":15},{"id":"common.rights","title":"Learn your work rights","detail":"Every worker in NZ has the same minimum rights: a written employment agreement, at least minimum wage, holidays and sick leave. Your visa may add limits on hours or employer.","xp":15,"link":{"href":"https://www.employment.govt.nz","label":"Employment NZ"}},{"id":"registered.arrive.rent","title":"Know your renting rights before you sign","detail":"A bond can be at most four weeks'' rent, and your landlord must lodge it with Tenancy Services. Never pay a bond in cash without a receipt.","xp":15,"link":{"href":"https://www.tenancy.govt.nz","label":"Tenancy Services"}}]}]}'::jsonb, '2026-11-04', 'KiwiPath content team (needs licensed adviser review)'),
  ('family', '{"id":"family","name":"Partner & family","short":"Join a partner","tint":"lavender","icon":"heart","summary":"Join a partner who is a New Zealand citizen or resident, or who holds an eligible work or student visa. Your visa type depends on your partner''s.","whoFor":["Your partner lives in, or is moving to, New Zealand","You live together in a genuine and stable relationship","You can show evidence of your relationship over time"],"steps":[{"title":"Check your partner can support you","detail":"Citizens, residents and some work and student visa holders can support a partner. The rules depend on their visa type and occupation."},{"title":"Gather relationship evidence","detail":"Joint leases, shared bills and bank accounts, photos over time, travel together and messages. A marriage certificate alone is not enough."},{"title":"Apply for the right partner visa","detail":"Temporary partner visas let you live, and often work, in NZ. Partnership-based residence usually needs you to have lived together for at least 12 months."},{"title":"Include your children","detail":"Dependent children can usually be included in, or apply alongside, the family''s applications."}],"requirements":["Evidence of a genuine and stable relationship, including living together","Your partner''s eligibility to support you","Certified translations of Sinhala or Tamil certificates","Health and character requirements"],"timeline":"Usually 3 to 12 months, depending on the visa","residence":"Partnership-based residence is possible if your partner is a citizen or resident and you meet the relationship requirements.","watchOuts":["Start collecting relationship evidence early. Time apart needs explaining.","Parents of NZ citizens and residents have separate visitor and resident options. Check them on immigration.govt.nz."],"sources":[{"label":"Immigration New Zealand","href":"https://www.immigration.govt.nz"},{"label":"Immigration Advisers Authority (find a licensed adviser)","href":"https://www.iaa.govt.nz"}],"checked":"Nov 2026","documents":["passport","photo","marriage","birth","relationship","police","medical"],"levels":[{"id":"family.start","title":"Find your path","summary":"Work out which partner visa applies.","icon":"compass","tasks":[{"id":"common.finder","title":"Complete the Pathway Finder","detail":"Answer a few questions so KiwiPath can suggest the paths that suit you.","xp":40,"link":{"to":"/welcome","label":"Open Pathway Finder"}},{"id":"family.start.guide","title":"Read the partner & family guide","detail":"Understand evidence and timing.","xp":10,"link":{"to":"/paths/family","label":"Open guide"}}]},{"id":"family.evidence","title":"Relationship evidence","summary":"Build a clear record of your life together.","icon":"heart","tasks":[{"id":"family.evidence.living","title":"Collect proof you live together","detail":"Leases, utility bills and letters at the same address.","xp":30},{"id":"family.evidence.money","title":"Show shared finances","detail":"Joint accounts, transfers and shared expenses.","xp":20},{"id":"family.evidence.timeline","title":"Write a short relationship timeline","detail":"Key dates: when you met, moved in, married and any time apart.","xp":20},{"id":"common.translations","title":"Get certified translations of Sinhala or Tamil documents","detail":"Documents not in English (birth and marriage certificates, for example) need certified English translations.","xp":15,"link":{"to":"/tools/documents","label":"Track documents"}}]},{"id":"family.visa","title":"Visa application","summary":"Certificates and your application.","icon":"stamp","tasks":[{"id":"common.passport","title":"Check your passport''s expiry date","detail":"Your passport should stay valid for your whole planned stay. Renew early: it is the first document every application asks for.","xp":10,"link":{"to":"/tools/documents","label":"Open Documents"}},{"id":"common.police","title":"Request a police clearance certificate","detail":"Most visas lasting longer than a short visit need a police certificate from each country you have lived in for a set period. In Sri Lanka these come from Sri Lanka Police.","xp":20,"link":{"href":"https://www.police.lk","label":"Sri Lanka Police"}},{"id":"common.medical","title":"Book your medical and chest X-ray if asked","detail":"Longer stays usually need a medical certificate and/or chest X-ray from an Immigration NZ panel physician. Check which ones your visa needs before you book.","xp":20},{"id":"common.adviser","title":"Confirm any adviser is licensed","detail":"In New Zealand law, anyone giving you immigration advice (in NZ or overseas) must be a licensed immigration adviser or a lawyer, unless exempt. Ask for their licence number and check it on the public register.","xp":20,"link":{"href":"https://www.iaa.govt.nz","label":"Search the register"}},{"id":"family.visa.submit","title":"Submit your partner visa application","detail":"Apply online and keep your application number.","xp":40}]},{"id":"family.move","title":"Get ready to fly","summary":"Budget, travel and settling in.","icon":"plane","tasks":[{"id":"common.budget","title":"Build your moving budget","detail":"Add up visa, travel and set-up costs in NZD and rupees, and set a monthly savings goal.","xp":30,"link":{"to":"/tools/money","label":"Open Money Planner"}},{"id":"common.biosecurity","title":"Pack for New Zealand''s border rules","detail":"New Zealand has strict biosecurity rules. Declare all food, plants and animal products on your arrival card, or leave them at home. Undeclared items can mean an instant fine.","xp":10},{"id":"common.quiz","title":"Score 80% on the Kiwi Life quiz","detail":"Slang, road rules, renting and work basics: the things nobody tells you before you land.","xp":30,"link":{"to":"/tools/quiz","label":"Play Kiwi Life"}}]},{"id":"family.arrive","title":"First 30 days","summary":"Set up the basics so work, study and everyday life run smoothly.","icon":"home","tasks":[{"id":"common.ird","title":"Apply for an IRD number","detail":"Your tax number from Inland Revenue. Apply as soon as you arrive; employers need it to pay you at the right tax rate.","xp":20,"link":{"href":"https://www.ird.govt.nz","label":"Inland Revenue"}},{"id":"common.bank","title":"Open a New Zealand bank account","detail":"Some banks let you start the process before you arrive. Bring your passport and proof of address.","xp":15},{"id":"common.sim","title":"Get a local SIM or eSIM","detail":"You''ll need an NZ mobile number for banks, employers and two-factor codes. Prepaid plans are easy to start with.","xp":10},{"id":"common.gp","title":"Enrol with a GP (family doctor)","detail":"Enrolling with a local medical centre makes appointments easier and can make them cheaper if you are eligible for public health funding.","xp":15},{"id":"common.rights","title":"Learn your work rights","detail":"Every worker in NZ has the same minimum rights: a written employment agreement, at least minimum wage, holidays and sick leave. Your visa may add limits on hours or employer.","xp":15,"link":{"href":"https://www.employment.govt.nz","label":"Employment NZ"}},{"id":"family.arrive.rent","title":"Know your renting rights before you sign","detail":"A bond can be at most four weeks'' rent, and your landlord must lodge it with Tenancy Services. Never pay a bond in cash without a receipt.","xp":15,"link":{"href":"https://www.tenancy.govt.nz","label":"Tenancy Services"}}]}]}'::jsonb, '2026-11-04', 'KiwiPath content team (needs licensed adviser review)'),
  ('business', '{"id":"business","name":"Business & investor","short":"Invest or build a business","tint":"teal","icon":"trend","summary":"For experienced business owners and investors with significant capital. These visas are complex, so talk to a licensed immigration adviser early.","whoFor":["You have a successful business track record","You have significant funds to invest in New Zealand","You''re prepared for a detailed business plan or investment process"],"steps":[{"title":"Compare business and investor visas","detail":"Options include visas for investors and for people who buy or set up a business. Each has its own capital and experience thresholds."},{"title":"Get professional advice","detail":"Use a licensed immigration adviser and an NZ accountant or lawyer for structure, tax and due diligence."},{"title":"Prepare evidence of funds and experience","detail":"Show where your funds came from (source of funds) and your business history."},{"title":"Apply and meet your conditions","detail":"Most business visas come with conditions you must meet before you can get residence."}],"requirements":["Significant investment or business capital","Evidence of the lawful source of your funds","Business experience or a credible business plan","Health and character requirements"],"timeline":"Usually 6 to 18 months","residence":"Some investor and business visas lead to residence once their conditions are met.","watchOuts":["Be cautious of business-for-sale schemes that promise a visa.","Thresholds change. Confirm current figures on immigration.govt.nz."],"sources":[{"label":"Immigration New Zealand","href":"https://www.immigration.govt.nz"},{"label":"Immigration Advisers Authority (find a licensed adviser)","href":"https://www.iaa.govt.nz"}],"checked":"Nov 2026","documents":["passport","funds","business","police","medical"],"levels":[{"id":"business.start","title":"Find your path","summary":"Understand the investor and business options.","icon":"compass","tasks":[{"id":"common.finder","title":"Complete the Pathway Finder","detail":"Answer a few questions so KiwiPath can suggest the paths that suit you.","xp":40,"link":{"to":"/welcome","label":"Open Pathway Finder"}},{"id":"common.adviser","title":"Confirm any adviser is licensed","detail":"In New Zealand law, anyone giving you immigration advice (in NZ or overseas) must be a licensed immigration adviser or a lawyer, unless exempt. Ask for their licence number and check it on the public register.","xp":20,"link":{"href":"https://www.iaa.govt.nz","label":"Search the register"}},{"id":"business.start.compare","title":"Compare business visa options","detail":"Note each option''s capital and experience thresholds.","xp":20,"link":{"href":"https://www.immigration.govt.nz","label":"Immigration NZ"}}]},{"id":"business.plan","title":"Plan & evidence","summary":"Prepare a credible plan and proof of funds.","icon":"files","tasks":[{"id":"business.plan.funds","title":"Document the source of your funds","detail":"Statements, sale agreements and tax records that show how you earned the money.","xp":30},{"id":"business.plan.plan","title":"Draft your business plan","detail":"Market research, budget and hiring plans for New Zealand.","xp":30},{"id":"common.scam-check","title":"Check any agent or offer with Scam Shield","detail":"Paste a WhatsApp message, email or offer letter. Scam Shield flags upfront fees, visa guarantees and other warning signs.","xp":30,"link":{"to":"/tools/scam-shield","label":"Open Scam Shield"}}]},{"id":"business.visa","title":"Visa application","summary":"Certificates and your application.","icon":"stamp","tasks":[{"id":"common.passport","title":"Check your passport''s expiry date","detail":"Your passport should stay valid for your whole planned stay. Renew early: it is the first document every application asks for.","xp":10,"link":{"to":"/tools/documents","label":"Open Documents"}},{"id":"common.police","title":"Request a police clearance certificate","detail":"Most visas lasting longer than a short visit need a police certificate from each country you have lived in for a set period. In Sri Lanka these come from Sri Lanka Police.","xp":20,"link":{"href":"https://www.police.lk","label":"Sri Lanka Police"}},{"id":"common.medical","title":"Book your medical and chest X-ray if asked","detail":"Longer stays usually need a medical certificate and/or chest X-ray from an Immigration NZ panel physician. Check which ones your visa needs before you book.","xp":20},{"id":"business.visa.submit","title":"Submit your application","detail":"With your adviser''s help.","xp":40}]},{"id":"business.arrive","title":"First 30 days","summary":"Set up the basics so work, study and everyday life run smoothly.","icon":"home","tasks":[{"id":"common.ird","title":"Apply for an IRD number","detail":"Your tax number from Inland Revenue. Apply as soon as you arrive; employers need it to pay you at the right tax rate.","xp":20,"link":{"href":"https://www.ird.govt.nz","label":"Inland Revenue"}},{"id":"common.bank","title":"Open a New Zealand bank account","detail":"Some banks let you start the process before you arrive. Bring your passport and proof of address.","xp":15},{"id":"common.sim","title":"Get a local SIM or eSIM","detail":"You''ll need an NZ mobile number for banks, employers and two-factor codes. Prepaid plans are easy to start with.","xp":10},{"id":"common.gp","title":"Enrol with a GP (family doctor)","detail":"Enrolling with a local medical centre makes appointments easier and can make them cheaper if you are eligible for public health funding.","xp":15},{"id":"common.rights","title":"Learn your work rights","detail":"Every worker in NZ has the same minimum rights: a written employment agreement, at least minimum wage, holidays and sick leave. Your visa may add limits on hours or employer.","xp":15,"link":{"href":"https://www.employment.govt.nz","label":"Employment NZ"}},{"id":"business.arrive.rent","title":"Know your renting rights before you sign","detail":"A bond can be at most four weeks'' rent, and your landlord must lodge it with Tenancy Services. Never pay a bond in cash without a receipt.","xp":15,"link":{"href":"https://www.tenancy.govt.nz","label":"Tenancy Services"}}]}]}'::jsonb, '2026-11-04', 'KiwiPath content team (needs licensed adviser review)')
